// Promise is eager and one-shot; a tiny Observable is lazy and cancellable.
let log = [];
const p = new Promise(res => { log.push('promise work started'); res(1); });
log.push('promise created');

function Observable(producer) { this.producer = producer; }
Observable.prototype.subscribe = function (next) {
  return this.producer({ next }) || (() => {}); // returns teardown
};
const obs = new Observable(o => {
  log.push('observable work started');
  let n = 0;
  const id = setInterval(() => o.next(++n), 10);
  return () => { clearInterval(id); log.push('teardown ran'); };
});
log.push('observable created (nothing started yet)');

const seen = [];
const unsub = obs.subscribe(v => seen.push(v)); // lazy: starts now
setTimeout(() => {
  unsub(); // cancel: Promise cannot do this
  p.then(v => seen.push('promise:' + v));
  setTimeout(() => {
    console.log(log.join('\n'));
    console.log('values seen:', seen.length > 0 ? 'several ticks, then promise:1' : 'none');
    console.log(seen[seen.length - 1]);
  }, 20);
}, 55);

// Subject vs BehaviorSubject vs ReplaySubject, built from scratch.
class Subject {
  constructor() { this.subs = []; }
  subscribe(fn) { this.subs.push(fn); }
  next(v) { this.subs.forEach(f => f(v)); }
}
class BehaviorSubject extends Subject {
  constructor(init) { super(); this.value = init; }
  subscribe(fn) { fn(this.value); super.subscribe(fn); } // current value first
  next(v) { this.value = v; super.next(v); }
}
class ReplaySubject extends Subject {
  constructor(n) { super(); this.n = n; this.buf = []; }
  subscribe(fn) { this.buf.forEach(fn); super.subscribe(fn); } // replay last n
  next(v) { this.buf.push(v); if (this.buf.length > this.n) this.buf.shift(); super.next(v); }
}
const subjects = {
  Subject: new Subject(),
  BehaviorSubject: new BehaviorSubject(0),
  ReplaySubject: new ReplaySubject(2),
};
for (const name in subjects) {
  const s = subjects[name];
  [1, 2, 3].forEach(v => s.next(v));      // emitted before anyone subscribes late
  const got = [];
  s.subscribe(v => got.push(v));          // late subscriber
  s.next(4);
  console.log(name.padEnd(16), 'late subscriber got', JSON.stringify(got));
}

// A tiny signal / computed / effect with automatic dependency tracking.
let current = null;
function signal(v) {
  const subs = new Set();
  const read = () => { if (current) subs.add(current); return v; };
  read.set = nv => { if (Object.is(nv, v)) return; v = nv; [...subs].forEach(s => s()); };
  return read;
}
function effect(fn) {
  const run = () => { const prev = current; current = run; try { fn(); } finally { current = prev; } };
  run();
}
function computed(fn) {
  let cache, dirty = true; const out = signal();
  const mark = () => { dirty = true; out.set(Symbol()); }; // tell readers
  const read = () => {
    if (dirty) { const prev = current; current = mark; cache = fn(); current = prev; dirty = false; }
    out(); // register the reader as a dependent
    return cache;
  };
  return read;
}
const price = signal(10);
const qty = signal(2);
let computeCount = 0;
const total = computed(() => { computeCount++; return price() * qty(); });
effect(() => console.log('effect: total =', total()));
price.set(20);
price.set(20); // same value: skipped
qty.set(3);
console.log('total read again:', total(), '| computed ran', computeCount, 'times');

// retry with exponential backoff and jitter; only transient errors are retried.
let calls = 0;
function flaky() {
  calls++;
  if (calls < 3) { const e = new Error('503 unavailable'); e.status = 503; throw e; }
  return 'ok after ' + calls + ' calls';
}
function delayFor(attempt) {
  const base = 100 * 2 ** (attempt - 1);        // 100, 200, 400 ...
  return Math.round(base * 0.5);                // fixed "jitter" factor so output is stable
}
function retry(fn, max) {
  for (let attempt = 1; ; attempt++) {
    try { return fn(); }
    catch (e) {
      const transient = e.status >= 500;        // never retry 4xx
      if (!transient || attempt > max) throw e;
      console.log('attempt', attempt, 'failed (' + e.message + '), wait', delayFor(attempt), 'ms');
    }
  }
}
console.log(retry(flaky, 3));
try { retry(() => { const e = new Error('400 bad input'); e.status = 400; throw e; }, 3); }
catch (e) { console.log('not retried:', e.message); }

// Push-pull with versions: diamond graph a -> b,c -> d recomputes d once, no glitch.
class Node {
  constructor(fn, deps) { this.fn = fn; this.deps = deps; this.version = 0; this.seen = deps.map(() => -1); this.value = undefined; this.runs = 0; }
  get() {
    let changed = this.version === 0;
    this.deps.forEach((d, i) => { d.get(); if (d.version !== this.seen[i]) { changed = true; this.seen[i] = d.version; } });
    if (changed) { // pull: recompute only if an input version moved
      const nv = this.fn(...this.deps.map(d => d.value)); this.runs++;
      if (!Object.is(nv, this.value)) { this.value = nv; this.version++; } // equality cutoff
    }
    return this.value;
  }
}
const a = { value: 1, version: 1, get() { return this.value; }, set(v) { this.value = v; this.version++; } };
const b = new Node(x => x * 2, [a]);
const c = new Node(x => x * 3, [a]);
const d = new Node((x, y) => x + y, [b, c]);
const parity = new Node(x => x % 2, [a]);
console.log('d =', d.get(), 'parity =', parity.get());
a.set(3);
console.log('d =', d.get(), '(b=6, c=9, never a mix)');
a.set(5); // parity stays 1: cutoff
console.log('d =', d.get(), 'parity =', parity.get(), '| d ran', d.runs, 'times, parity ran', parity.runs);
